-- LifeLine 0.3.0 - versione applicativa + modelli di chiamata
UPDATE lifeline_settings SET value = '0.3.0' WHERE key_name = 'app_version';

SET NAMES utf8mb4;

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('IMP_003', 'Farmacia di turno', 'impropria', 1, 1, 90, 1, 'sera,notte', 0, 0, '{"code":"IMP_003","title":"Farmacia di turno","category":"impropria","phase":1,"difficulty":1,"weight":90,"min_rank":1,"time_bands":["sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale","colline"],"floor":[0,3]},"req":{"choice":[{"text":"No no, nessuna emergenza, per carità. Mi serve solo un collirio.","display":"Nessuna emergenza: cerca un collirio","detail_text":"Nessun dolore, è solo per gli occhi un po'' irritati.","detail_display":"Nessun sintomo rilevante","event":"impropria.informazioni","agencies":[]},{"text":"Beh… mia figlia ha la febbre a 39 da stasera, volevo prendere uno sciroppo.","display":"La figlia ha febbre a 39, cerca un antipiretico","detail_text":"È un po'' abbattuta ma gioca, beve, risponde normalmente.","detail_display":"Bambina vigile, beve e risponde","event":"impropria.informazioni","agencies":[]},{"text":"Ecco… è per mio marito. Ha un dolore al petto da un''ora, pensavo a un antiacido…","display":"Il marito ha dolore al petto da un''ora","detail_text":"Gli prende tutto il petto e va verso il braccio sinistro… ed è tutto sudato.","detail_display":"Dolore al petto irradiato al braccio sinistro, sudorazione","event":"sanitaria.dolore_toracico","agencies":["118"]}],"weights":[55,30,15]}},"caller":{"gender":"f","phone_type":"any","panic_start":5,"ring_patience_s":60,"hold_patience_s":90,"reliability":1,"callback_chance":0.3},"opening":{"calm":"Salve, scusi il disturbo… volevo sapere qual è la farmacia di turno stanotte.","panic":"Salve, scusi… mi serve una farmacia aperta, qual è quella di turno?"},"facts":{"richiesta":{"display":"{req.display}"},"stato":{"display":"{req.detail_display}"},"indirizzo":{"display":"{location.street} {location.number}, {location.zone_name}"}},"nodes":[{"id":"q_emergenza","label":"Per chi le serve? C''è qualcuno che sta male adesso?","cost_s":6,"reveals":["richiesta"],"reply":{"calm":"{req.text}","panic":"{req.text}"}},{"id":"q_dettagli","label":"Mi descriva i sintomi: da quanto tempo e come sta adesso?","cost_s":8,"requires":["q_emergenza"],"reveals":["stato"],"reply":{"calm":"{req.detail_text}","panic":"{req.detail_text}"}},{"id":"q_dove","label":"Da dove chiama? Mi dica l''indirizzo.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"Da casa, in {location.street} {location.number}.","panic":"{location.street} {location.number}."}}],"truth":{"event_type":"{req.event}","agencies_required":["{req.agencies}"],"severity":{"optimal_s":240,"acceptable_s":600,"limit_s":1500},"critical_facts":["richiesta"],"hint_debrief":"Le chiamate per informazioni vanno chiuse in fretta, ma solo dopo aver escluso un''emergenza: a volte chi chiede una farmacia sta descrivendo un infarto."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('IMP_004', 'Scherzo telefonico', 'impropria', 1, 2, 80, 1, 'pomeriggio,sera', 0, 0, '{"code":"IMP_004","title":"Scherzo telefonico","category":"impropria","phase":1,"difficulty":2,"weight":80,"min_rank":1,"time_bands":["pomeriggio","sera"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["residenziale","centro"],"floor":[0,0]},"prank":{"choice":[{"opening":"(risatine in sottofondo) Pronto… c''è un incendio… sulla Luna!","where":"Sulla Luna, gliel''ho detto! (risate)","where_display":"Dice «sulla Luna», tra le risate"},{"opening":"C''è… c''è un incendio in {location.street}! (una risata soffocata)","where":"Ehm… in {location.street}… al… al numero mille! (risate)","where_display":"{location.street} «numero mille», tra le risate"},{"opening":"Pronto, polizia? Il mio amico è stato rapito dagli alieni!","where":"Nel campo dietro la scuola… anzi no, su Marte!","where_display":"Indicazioni contraddittorie, tra le risate"}]}},"caller":{"gender":"m","phone_type":"mobile","panic_start":5,"ring_patience_s":20,"hold_patience_s":10,"reliability":0.3,"callback_chance":0.15},"opening":{"calm":"{prank.opening}","panic":"{prank.opening}"},"facts":{"indirizzo":{"display":"{prank.where_display}"},"evento":{"display":"Racconto confuso, cambia versione"},"ambiente":{"label":"Rumori di fondo","display":"Risate di altri ragazzi, nessun rumore di emergenza"}},"nodes":[{"id":"q_dove","label":"Dove si trova esattamente?","cost_s":5,"reveals":["indirizzo"],"reply":{"calm":"{prank.where}","panic":"{prank.where}"}},{"id":"q_ripeti","label":"Mi ripeta con calma cosa sta succedendo.","cost_s":6,"reveals":["evento"],"reply":{"calm":"Eh… c''è… c''è un problema grosso! (si sente qualcuno che gli suggerisce qualcosa)","panic":"C''è un problema grosso!"}},{"id":"q_ambiente","label":"Sento delle voci. Chi c''è lì con te?","cost_s":5,"reveals":["ambiente"],"reply":{"calm":"Nessuno! (in sottofondo: «dai, digli che…» e altre risate)","panic":"Nessuno, nessuno!"}},{"id":"q_adulto","label":"Quanti anni hai? Passami un adulto, per favore.","cost_s":5,"ends_call":true,"reply":{"calm":"(risate, poi riattaccano)","panic":"(riattaccano)"}}],"truth":{"event_type":"impropria.scherzo","agencies_required":[],"severity":{"optimal_s":60,"acceptable_s":120,"limit_s":600},"critical_facts":["indirizzo"],"hint_debrief":"Uno scherzo si riconosce da incoerenze e rumori di fondo; va chiuso rapidamente per liberare la linea, ma solo dopo un paio di verifiche."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('INC_002', 'Cassonetto in fiamme', 'incendio_tecnico', 1, 1, 110, 1, 'pomeriggio,sera,notte', 1, 0, '{"code":"INC_002","title":"Cassonetto in fiamme","category":"incendio_tecnico","phase":1,"difficulty":1,"weight":110,"min_rank":1,"time_bands":["pomeriggio","sera","notte"],"can_duplicate":true,"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale","industriale"],"floor":[0,0]},"fire":{"choice":[{"text":"Un cassonetto della plastica, le fiamme saranno alte un metro.","display":"Un cassonetto, fiamme di circa un metro","danger_text":"No, è in mezzo al parcheggio, lontano da tutto.","danger_display":"Lontano da case e auto"},{"text":"Due cassonetti, e il fuoco sta arrivando a una macchina parcheggiata!","display":"Due cassonetti, fiamme vicine a un''auto","danger_text":"Sì! C''è una macchina attaccata, e sopra ci sono le finestre delle case!","danger_display":"Auto parcheggiata e finestre di abitazioni vicine"}],"weights":[65,35]},"people":{"choice":[{"text":"No, qui non c''è nessuno, solo io che guardo.","display":"Nessun ferito","agencies":[]},{"text":"Un signore ha provato a spegnerlo con un secchio e si è bruciato la mano.","display":"Un uomo si è ustionato la mano","agencies":["118"]}],"weights":[80,20]}},"caller":{"gender":"m","phone_type":"mobile","panic_start":15,"ring_patience_s":25,"hold_patience_s":35,"reliability":1,"callback_chance":0.2},"opening":{"calm":"Buonasera, sto passando in {location.street}: c''è un cassonetto che brucia.","panic":"Pronto! C''è un incendio qui in {location.street}, un cassonetto!"},"facts":{"indirizzo":{"display":"{location.street} altezza civico {location.number}, vicino a {location.landmark} ({location.zone_name})"},"incendio":{"display":"{fire.display}"},"pericoli":{"display":"{fire.danger_display}"},"persone":{"display":"{people.display}"}},"nodes":[{"id":"q_dove","label":"Dove si trova esattamente? Mi dia un civico o un punto di riferimento.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"In {location.street}, all''altezza del {location.number}, vicino a {location.landmark}.","panic":"In {location.street}, vicino a {location.landmark}!"}},{"id":"q_cosa","label":"Cosa sta bruciando? Quanto sono alte le fiamme?","cost_s":6,"reveals":["incendio"],"reply":{"calm":"{fire.text}","panic":"{fire.text}"}},{"id":"q_vicino","label":"Il fuoco è vicino a case, auto o alberi?","cost_s":5,"requires":["q_cosa"],"reveals":["pericoli"],"reply":{"calm":"{fire.danger_text}","panic":"{fire.danger_text}"}},{"id":"q_persone","label":"Ci sono persone ferite o in pericolo?","cost_s":5,"reveals":["persone"],"reply":{"calm":"{people.text}","panic":"{people.text}"}},{"id":"a_sicurezza","type":"reassure","label":"Si tenga a distanza e non provi a spegnerlo: i soccorsi stanno arrivando.","cost_s":5,"panic_delta":-10,"reply":{"calm":"D''accordo, resto qui sul marciapiede.","panic":"Va bene, va bene, mi allontano."}}],"truth":{"event_type":"incendio_tecnico.incendio_rifiuti","agencies_required":["115","{people.agencies}"],"severity":{"optimal_s":240,"acceptable_s":600,"limit_s":1500},"critical_facts":["indirizzo","persone"],"hint_debrief":"Chiedere sempre se ci sono feriti: anche un incendio banale può richiedere il 118."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SAN_001', 'Anziana caduta in casa', 'sanitaria', 1, 1, 120, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"SAN_001","title":"Anziana caduta in casa","category":"sanitaria","phase":1,"difficulty":1,"weight":120,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale"],"floor":[0,4]},"injury":{"choice":[{"text":"Mi fa tanto male l''anca destra… la testa no, quella non l''ho battuta.","display":"Forte dolore all''anca destra, non ha battuto la testa"},{"text":"Ho battuto la testa sullo spigolo del tavolo… mi gira un po'' tutto.","display":"Ha battuto la testa, ha dei capogiri"},{"text":"Il polso… credo di essermelo rotto. La testa no.","display":"Dolore al polso, non ha battuto la testa"}]},"access":{"choice":[{"text":"No, sono sola. La porta è chiusa a chiave e le chiavi sono sul mobile dell''ingresso… non ci arrivo.","display":"Sola in casa, porta chiusa a chiave: non può aprire","agencies":["118","115"]},{"text":"Sono sola, ma la signora del piano di sopra ha le chiavi, può aprire lei.","display":"Sola; la vicina del piano di sopra ha le chiavi","agencies":["118"]},{"text":"C''è mio nipote, l''ho mandato giù ad aprire il portone.","display":"C''è il nipote, che aprirà ai soccorsi","agencies":["118"]}],"weights":[40,35,25]}},"caller":{"gender":"f","phone_type":"any","panic_start":30,"ring_patience_s":45,"hold_patience_s":70,"reliability":0.9,"callback_chance":0.7},"opening":{"calm":"Pronto? Scusi… sono caduta in cucina e non riesco più ad alzarmi.","panic":"Pronto?! Aiuto… sono caduta, non riesco ad alzarmi, mi fa male!"},"facts":{"indirizzo":{"display":"{location.street} {location.number}, {location.zone_name}"},"piano":{"display":"{location.floor_text}, campanello {caller_surname}"},"evento":{"display":"Scivolata in cucina, non riesce ad alzarsi"},"ferite":{"display":"{injury.display}"},"accesso":{"label":"Accesso all''abitazione","display":"{access.display}"}},"nodes":[{"id":"q_dove","label":"Mi dica l''indirizzo: via e numero civico.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"Abito in {location.street} {location.number}.","panic":"In {location.street}… il {location.number}, sì, il {location.number}."},"error":{"threshold":101,"fact":"indirizzo","display":"{location.street} {location.number_wrong}, {location.zone_name}","reply":{"calm":"In {location.street} {location.number_wrong}… sì, mi pare."}}},{"id":"q_piano","label":"A che piano abita? Che nome c''è sul campanello?","cost_s":5,"requires":["q_dove"],"reveals":["piano"],"reply":{"calm":"Al {location.floor_text}. Sul campanello c''è scritto {caller_surname}.","panic":"{location.floor_text}… {caller_surname}, c''è scritto {caller_surname}!"}},{"id":"q_cosa","label":"Mi racconti cosa è successo.","cost_s":7,"reveals":["evento"],"reply":{"calm":"Stavo prendendo un piatto, sono scivolata e sono finita per terra. Adesso non riesco a tirarmi su.","panic":"Sono scivolata! Sono per terra e non riesco ad alzarmi!"}},{"id":"q_dolore","label":"Ha male da qualche parte? Ha sbattuto la testa?","cost_s":7,"requires":["q_cosa"],"reveals":["ferite"],"reply":{"calm":"{injury.text}","panic":"{injury.text}"}},{"id":"q_accesso","label":"C''è qualcuno con lei? Chi può aprire la porta ai soccorsi?","cost_s":7,"reveals":["accesso"],"reply":{"calm":"{access.text}","panic":"{access.text}"}},{"id":"a_rassicura","type":"reassure","label":"Signora, non si muova e stia tranquilla: le mando subito aiuto.","cost_s":6,"panic_delta":-20,"reply":{"calm":"Va bene… grazie, grazie tanto.","panic":"Sì… sì, va bene. Faccia presto però."}}],"truth":{"event_type":"sanitaria.trauma_caduta","agencies_required":["{access.agencies}"],"severity":{"optimal_s":300,"acceptable_s":900,"limit_s":2400},"critical_facts":["indirizzo","accesso"],"hint_debrief":"Una persona sola che non può aprire la porta richiede anche i Vigili del fuoco per l''accesso: senza, l''ambulanza resta fuori."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SAN_007', 'Non si sveglia (arresto cardiaco mascherato)', 'sanitaria', 1, 3, 90, 1, 'mattina,pomeriggio,sera,notte', 0, 0, '{"code":"SAN_007","title":"Non si sveglia (arresto cardiaco mascherato)","category":"sanitaria","phase":1,"difficulty":3,"weight":90,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["centro","residenziale","colline"],"floor":[0,5]},"patient":{"choice":[{"rel":"marito","my":"Mio marito","him":"lo"},{"rel":"compagno","my":"Il mio compagno","him":"lo"},{"rel":"papà","my":"Mio papà","him":"lo"}]},"patient_age":{"range":[58,79]}},"caller":{"gender":"f","phone_type":"any","panic_start":65,"ring_patience_s":30,"hold_patience_s":20,"reliability":0.95,"callback_chance":0.9},"opening":{"calm":"Pronto? {patient.my} non si sveglia… sembra che dorma ma non mi risponde.","panic":"Pronto?! {patient.my} non si sveglia, non mi risponde! Faccia presto!"},"facts":{"indirizzo":{"display":"{location.street} {location.number}, {location.zone_name}"},"piano":{"display":"{location.floor_text}, citofono {caller_surname}"},"coscienza":{"display":"Non risponde e non reagisce quando lo scuote"},"respiro":{"display":"Fa dei rantoli ogni tanto, «come se russasse»"},"eta":{"display":"{patient_age} anni"},"pericoli":{"display":"Nessun odore di gas o fumo"}},"nodes":[{"id":"q_dove","label":"Mi dica l''indirizzo esatto.","cost_s":6,"reveals":["indirizzo"],"reply":{"calm":"{location.street} {location.number}.","panic":"{location.street}… il {location.number}! Venite!"},"error":{"threshold":60,"chance":0.5,"fact":"indirizzo","display":"{location.street} {location.number_wrong}, {location.zone_name}","reply":{"panic":"{location.street}… il {location.number_wrong}! Faccia presto!"}}},{"id":"q_piano","label":"Che piano? Che nome c''è sul citofono?","cost_s":5,"requires":["q_dove"],"reveals":["piano"],"reply":{"calm":"Al {location.floor_text}, citofono {caller_surname}.","panic":"{location.floor_text}! {caller_surname}!"}},{"id":"q_coscienza","label":"Lo chiami forte e lo scuota per le spalle. Risponde?","cost_s":10,"panic_delta":5,"reveals":["coscienza"],"reply":{"calm":"No… non risponde, niente.","panic":"No! Non fa niente! Oddio!"}},{"id":"q_respiro","label":"Guardi il petto: respira normalmente?","cost_s":10,"requires":["q_coscienza"],"reveals":["respiro"],"reply":{"calm":"Fa… tipo dei rantoli, ogni tanto. Come se russasse.","panic":"Fa un rumore strano… tipo russare…"},"error":{"threshold":70,"chance":0.6,"fact":"respiro","display":"Dice che respira normalmente","reply":{"panic":"Sì, sì, respira! Cioè… credo di sì!"}}},{"id":"q_eta","label":"Quanti anni ha?","cost_s":4,"reveals":["eta"],"reply":{"calm":"{patient_age}.","panic":"{patient_age}, credo… sì, {patient_age}!"}},{"id":"q_pericoli","label":"Sente odore di gas o fumo in casa?","cost_s":5,"reveals":["pericoli"],"reply":{"calm":"No, niente.","panic":"No! Ma cosa c''entra?!"}},{"id":"a_rassicura","type":"reassure","label":"Signora, la sto aiutando. Respiri con me e mi segua.","cost_s":8,"panic_delta":-25,"reply":{"calm":"Sì… sì, va bene.","panic":"Va bene… va bene, ci provo."}}],"truth":{"event_type":"sanitaria.arresto_cardiaco","agencies_required":["118"],"agencies_acceptable":[],"severity":{"optimal_s":60,"acceptable_s":150,"limit_s":300},"critical_facts":["indirizzo","coscienza","respiro"],"hint_debrief":"«Dorme ma non risponde» + «fa un rumore strano» indica un respiro agonico: va trasferito come arresto cardiaco appena confermati coscienza e respiro assenti."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('SIC_006', 'Ladri in casa', 'sicurezza', 1, 3, 90, 1, 'mattina,sera,notte', 0, 0, '{"code":"SIC_006","title":"Ladri in casa","category":"sicurezza","phase":1,"difficulty":3,"weight":90,"min_rank":1,"time_bands":["mattina","sera","notte"],"lang":"it","variables":{"location":{"pool":"stradario","zones":["residenziale","colline"],"floor":[0,2]},"intruders":{"choice":[{"text":"(sussurra) Almeno due… li sento parlare. Non so se sono armati.","display":"Almeno due persone, armi non viste"},{"text":"(sussurra) Uno solo, credo… ha rotto il vetro della portafinestra.","display":"Una persona, entrata rompendo la portafinestra"}]},"car":{"choice":[{"text":"(sussurra, agitata) C''è una macchina scura col motore acceso davanti al cancello… non vedo la targa.","display":"Auto scura col motore acceso davanti al cancello"},{"text":"(sussurra) Non vedo niente… è tutto buio fuori.","display":"Nessun veicolo visibile"}]}},"caller":{"gender":"f","phone_type":"mobile","panic_start":60,"ring_patience_s":30,"hold_patience_s":15,"reliability":0.9,"callback_chance":0.9},"opening":{"calm":"(sussurra) Pronto… ci sono dei ladri in casa. Li sento al piano di sotto.","panic":"(sussurra, con il fiato corto) Pronto… sono in casa… sono in casa, li sento!"},"facts":{"indirizzo":{"display":"{location.street} {location.number}, {location.zone_name}"},"posizione":{"label":"Dove si trova la chiamante","display":"Chiusa a chiave in camera da letto, al piano di sopra"},"sospetti":{"display":"{intruders.display}"},"veicoli":{"display":"{car.display}"}},"nodes":[{"id":"q_dove","label":"Mi dica l''indirizzo: via e numero civico.","cost_s":7,"reveals":["indirizzo"],"reply":{"calm":"(sussurra) {location.street} {location.number}.","panic":"(sussurra) {location.street}… {location.number}…"},"error":{"threshold":70,"chance":0.45,"fact":"indirizzo","display":"{location.street} {location.number_wrong}, {location.zone_name}","reply":{"panic":"(sussurra) {location.street}… {location.number_wrong}…"}}},{"id":"q_posizione","label":"Lei dove si trova adesso? È al sicuro?","cost_s":6,"reveals":["posizione"],"reply":{"calm":"(sussurra) In camera, al piano di sopra. Ho chiuso la porta a chiave.","panic":"(sussurra) In camera… ho chiuso a chiave… ho paura."}},{"id":"q_quanti","label":"Quante persone sente? Ha visto armi?","cost_s":6,"reveals":["sospetti"],"reply":{"calm":"{intruders.text}","panic":"{intruders.text}"}},{"id":"q_auto","label":"Riesce a guardare dalla finestra senza farsi vedere? C''è un''auto fuori?","cost_s":12,"panic_delta":15,"reveals":["veicoli"],"reply":{"calm":"{car.text}","panic":"{car.text}"}},{"id":"a_silenzio","type":"reassure","label":"Resti dov''è, in silenzio, e non apra a nessuno. Io resto in linea con lei.","cost_s":6,"panic_delta":-18,"reply":{"calm":"(sussurra) Va bene… resto qui.","panic":"(sussurra) Sì… sì… non se ne vada, la prego."}}],"truth":{"event_type":"sicurezza.furto_in_corso","agencies_required":["{location.police}"],"severity":{"optimal_s":180,"acceptable_s":420,"limit_s":900},"critical_facts":["indirizzo","sospetti"],"hint_debrief":"Chi sussurra non può reggere lunghe attese: metterla in attesa o chiederle di muoversi aumenta il rischio. Competenza PS o CC secondo la zona."}}', 1, 1)
ON DUPLICATE KEY UPDATE
    content_version = IF(content_json <> VALUES(content_json), content_version + 1, content_version),
    title = VALUES(title), category = VALUES(category), phase = VALUES(phase), difficulty = VALUES(difficulty),
    weight = VALUES(weight), min_rank = VALUES(min_rank), time_bands = VALUES(time_bands),
    can_duplicate = VALUES(can_duplicate), is_story = VALUES(is_story), content_json = VALUES(content_json);

INSERT INTO lifeline_call_templates (code, title, category, phase, difficulty, weight, min_rank, time_bands, can_duplicate, is_story, content_json, content_version, is_active) VALUES
('STR_005', 'Tamponamento stradale', 'sicurezza', 1, 2, 100, 1, 'mattina,pomeriggio,sera,notte', 1, 0, '{"code":"STR_005","title":"Tamponamento stradale","category":"sicurezza","phase":1,"difficulty":2,"weight":100,"min_rank":1,"time_bands":["mattina","pomeriggio","sera","notte"],"can_duplicate":true,"lang":"it","variables":{"location":{"pool":"stradario","zones":["residenziale","industriale","colline"],"floor":[0,0]},"injury":{"choice":[{"text":"No, siamo tutti fuori dalle macchine, solo tanto spavento.","display":"Nessun ferito, tutti fuori dai veicoli","agencies":[],"event":"sicurezza.incidente_stradale"},{"text":"La signora dell''altra macchina dice che le fa male il collo, è ancora seduta dentro.","display":"Una donna con dolore al collo, ancora nel veicolo","agencies":["118"],"event":"sanitaria.trauma_stradale"}],"weights":[55,45]},"veh":{"choice":[{"text":"Due macchine. Niente fumo, solo il paraurti distrutto.","display":"Due auto, nessun fumo o perdita","agencies":[]},{"text":"Due macchine… e dalla mia esce del liquido sotto il motore, sento odore di benzina.","display":"Due auto, perdita di liquido e odore di benzina","agencies":["115"]}],"weights":[75,25]},"road":{"choice":[{"text":"Siamo a bordo strada, le macchine passano piano.","display":"Veicoli a bordo strada, traffico lento"},{"text":"Siamo in mezzo alla carreggiata, la gente frena all''ultimo!","display":"Veicoli in mezzo alla carreggiata, rischio di altri urti"}]}},"caller":{"gender":"m","phone_type":"mobile","panic_start":40,"ring_patience_s":35,"hold_patience_s":30,"reliability":0.95,"callback_chance":0.8},"opening":{"calm":"Pronto, buonasera. Ho appena avuto un incidente, un tamponamento.","panic":"Pronto?! C''è stato un incidente, mi hanno tamponato, qui è un casino!"},"facts":{"indirizzo":{"display":"{location.street}, vicino a {location.landmark} ({location.zone_name})"},"feriti":{"display":"{injury.display}"},"veicoli":{"display":"{veh.display}"},"pericoli":{"display":"{road.display}"}},"nodes":[{"id":"q_dove","label":"In che strada si trova? C''è un incrocio o un punto di riferimento?","cost_s":7,"reveals":["indirizzo"],"reply":{"calm":"In {location.street}, poco dopo {location.landmark}.","panic":"In {location.street}… vicino a {location.landmark}, credo!"},"error":{"threshold":65,"chance":0.35,"fact":"indirizzo","display":"{location.street_wrong} (incerto)","reply":{"panic":"In {location.street_wrong}… o forse no, non lo so, non sono di qui!"}}},{"id":"q_feriti","label":"Ci sono feriti? Qualcuno è rimasto dentro un''auto?","cost_s":6,"reveals":["feriti"],"reply":{"calm":"{injury.text}","panic":"{injury.text}"}},{"id":"q_veicoli","label":"Quanti veicoli sono coinvolti? Esce fumo o perdono liquidi?","cost_s":6,"reveals":["veicoli"],"reply":{"calm":"{veh.text}","panic":"{veh.text}"}},{"id":"q_strada","label":"Le auto bloccano la strada? È pericoloso per chi passa?","cost_s":5,"reveals":["pericoli"],"reply":{"calm":"{road.text}","panic":"{road.text}"}},{"id":"a_sicurezza","type":"reassure","label":"Accendete le quattro frecce e mettetevi al sicuro oltre il guardrail o sul marciapiede.","cost_s":6,"panic_delta":-15,"reply":{"calm":"Sì, va bene, lo dico anche agli altri.","panic":"Ok… ok, ci spostiamo."}}],"truth":{"event_type":"{injury.event}","agencies_required":["{location.police}","{injury.agencies}","{veh.agencies}"],"severity":{"optimal_s":300,"acceptable_s":900,"limit_s":1800},"critical_facts":["indirizzo","feriti","veicoli"],"hint_debrief":"In un incidente la competenza tra Polizia e Carabinieri dipende dalla zona; feriti e perdite di carburante aggiungono 118 e Vigili del fuoco."}}', 1, 1)
